 if(routeShape){const around=M.routeProgress(loadCenter.x,loadCenter.z,routeShape),ratio=route.distance/(routeShape.total||1);const start=Math.max(200,Math.floor((around.progress-loadedRadius)/500)*500+200),end=Math.min(routeShape.total,around.progress+loadedRadius);
 for(let d=start;d<end&&placed<10;d+=500){const p=M.pointAlong(routeShape,d);if(Math.hypot(p.x-loadCenter.x,p.z-loadCenter.z)>loadedRadius*.9)continue;const near=M.nearest(p.x,p.z,roads);if(!near.road||near.distance>30)continue;const offset=near.road.width/2+1.3,position={x:p.x+Math.cos(p.heading)*offset,z:p.z-Math.sin(p.heading)*offset,heading:p.heading};const intermediate=routePlaces.find(p=>p.progress>d+100&&p.progress-d<12000&&p.name.toLowerCase()!==route.from.name.toLowerCase()&&p.name.toLowerCase()!==route.to.name.toLowerCase());const target=intermediate?intermediate.name:route.to.name;const remaining=((intermediate?intermediate.progress:routeShape.total)-d)*ratio/1000,label=remaining>=1?`${remaining.toFixed(1)} km`:`${Math.round(remaining*1000)} m`;if(Math.round(d-200)%1000!==0){makeSign([target,label],position,.95,1.15,true);placed++;signPositions.push(position);}
 if(Math.round(d-200)%1000===0&&placed<12){const board={x:p.x+Math.cos(p.heading)*(offset+1.6),z:p.z-Math.sin(p.heading)*(offset+1.6),heading:p.heading};const big=makeSign([`${target} ${label} ↑`,`${route.to.name} ${((routeShape.total-d)*ratio/1000).toFixed(1)} km ↑`],{...board,x:p.x,z:p.z},Math.max(10,near.road.width+3),2.2);big.children[0].position.y=6;big.children.slice(1).forEach((child,i)=>{child.position.x=(i===0?-1:1)*(near.road.width/2+1.3);child.position.y=3.5;child.scale.y=2;});placed++;signPositions.push(board);}}
 }
 for(const poi of nearbyPlaces){if(placed>=14)break;if(poi.name.toLowerCase()===placeName.toLowerCase())continue;const n=M.nearest(poi.x,poi.z,roads);if(!n.road||n.distance>180||signPositions.some(p=>Math.hypot(p.x-n.x,p.z-n.z)<100))continue;if(routeShape&&M.nearest(n.x,n.z,[routeShape]).distance>100)continue;const offset=n.road.width/2+2.5;signPositions.push(n);makeSign([poi.name,poi.town?'Town / village':'Nearby attraction'],{x:n.x+Math.cos(n.heading)*offset,z:n.z-Math.sin(n.heading)*offset,heading:n.heading},4,1.7);placed++;}
