function updateJourneyHUD(){if(!route||!routeShape){$('journey-hud').hidden=true;return;}$('journey-hud').hidden=false;const progress=M.routeProgress(car.x,car.z,routeShape),ratio=route.distance/(routeShape.total||1),remaining=progress.remaining*ratio;const arrived=remaining<45&&progress.distance<35;$('journey-target').textContent=route.to.name;$('remaining').textContent=arrived?'Arrived':remaining>=1000?`${(remaining/1000).toFixed(1)} km`:`${Math.round(remaining)} m`;$('journey-progress').style.width=`${Math.min(100,progress.progress/routeShape.total*100)}%`;
 let instruction=arrived?`You’ve arrived in ${route.to.name}. Choose another drive ↗`:progress.distance>65?'Off route · rejoin the purple GPS line.':'Continue along the purple GPS route.';
 let best=null;for(const instruction of route.instructions){const ahead=(instruction.progress-progress.progress)*ratio;if(ahead>25&&(!best||ahead<best.ahead))best={step:instruction.step,ahead};}
 if(best&&progress.distance<=65&&!arrived){const modifier=best.step.maneuver.modifier||'',type=best.step.maneuver.type;const action=type==='arrive'?'Arrive':type.includes('roundabout')?'At the roundabout':modifier.includes('left')?'Turn left':modifier.includes('right')?'Turn right':'Continue';const dist=best.ahead>1000?`${(best.ahead/1000).toFixed(1)} km`:`${Math.round(best.ahead/10)*10} m`;instruction=`${action} in ${dist}${best.step.name?' · '+best.step.name:''}`;}$('instruction').textContent=instruction;
 const nearby=nearbyPlaces.filter(p=>Math.hypot(p.x-car.x,p.z-car.z)<600).sort((a,b)=>Math.hypot(a.x-car.x,a.z-car.z)-Math.hypot(b.x-car.x,b.z-car.z));const upcoming=routePlaces.find(p=>p.progress>progress.progress+40&&p.name!==route.to.name);$('nearby-label').textContent=upcoming?`Next: ${upcoming.name} · ${((upcoming.progress-progress.progress)*ratio/1000).toFixed(1)} km along route`:nearby.length?`Nearby: ${nearby.slice(0,2).map(p=>p.name).join(' · ')}`:'Road distance to destination · local scenery streamed';
}

